    case webSearchPreviewTool(WebSearchPreviewTool)
    /// `type`: `apply_patch`
    case applyPatch(ApplyPatchToolParam)
    /// A value this version of OpenAIKit does not recognize, kept as raw JSON.
    case unknown(JSONValue)

    public init(from decoder: any Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let keyed = try? decoder.container(keyedBy: OpenAIDynamicCodingKey.self),
           let discriminator = try? keyed.decode(String.self, forKey: OpenAIDynamicCodingKey("type")) {
            switch discriminator {
            case "function":
                self = .function(try container.decode(FunctionTool.self))
                return
            case "file_search":
                self = .fileSearch(try container.decode(FileSearchTool.self))
                return
            case "computer":
                self = .computer(try container.decode(ComputerTool.self))
                return
            case "computer_use_preview":
                self = .computerUsePreview(try container.decode(ComputerUsePreviewTool.self))
                return
            case "mcp":
                self = .mcp(try container.decode(MCPTool.self))
                return
            case "code_interpreter":
                self = .codeInterpreter(try container.decode(CodeInterpreterTool.self))
                return
            case "programmatic_tool_calling":
                self = .programmaticToolCalling(try container.decode(ProgrammaticToolCallingParam.self))
                return
            case "image_generation":
                self = .imageGeneration(try container.decode(ImageGenTool.self))
                return
            case "local_shell":
                self = .localShell(try container.decode(LocalShellToolParam.self))
                return
            case "shell":
                self = .shell(try container.decode(FunctionShellToolParam.self))
                return
            case "custom":
                self = .custom(try container.decode(CustomToolParam.self))
                return
            case "namespace":
                self = .namespace(try container.decode(ToolSearchOutputNamespaceToolParam.self))
                return
            case "tool_search":
                self = .toolSearch(try container.decode(ToolSearchToolParam.self))
                return
            case "web_search_preview", "web_search_preview_2025_03_11":
                self = .webSearchPreviewTool(try container.decode(WebSearchPreviewTool.self))
                return
            case "apply_patch":
                self = .applyPatch(try container.decode(ApplyPatchToolParam.self))
                return
            default:
                break
            }
        }
        if let value = try? container.decode(WebSearchTool.self) {
            self = .webSearchTool(value)
            return
        }
        self = .unknown(try container.decode(JSONValue.self))
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .function(let value):
            try container.encode(value)
        case .fileSearch(let value):
