/// Hosted or BYOT tool search configuration for deferred tools.
public struct ToolSearchToolParam: Codable, Hashable, Sendable {
    /// The type of the tool. Always `tool_search`.
    public var type: String = "tool_search"
    /// Whether tool search is executed by the server or by the client.
    public var execution: ToolSearchExecutionType?
    public var description: String?
    public var parameters: EmptyModelParam?

    public init(
        execution: ToolSearchExecutionType? = nil,
        description: String? = nil,
        parameters: EmptyModelParam? = nil
    ) {
        self.execution = execution
        self.description = description
        self.parameters = parameters
    }

    private enum CodingKeys: String, CodingKey {
        case type
        case execution
        case description
        case parameters
    }
}
